esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // We take arbitrary callee and data and attempt two forwards. We capture whether the first call reverted
    // and ensure that we can still call forward again (i.e., the contract wasn't destroyed or made unusable);
    // the assertion: the second call's revert-ness is a deterministic boolean value (true/false) and is reachable
    // — specifically we assert that performing the second call is possible (we reached the assert) and that its
    // revert flag is either true or false (non-dependent on reading internal storage). This encodes that forward
    // does not irreversibly break the contract such as by selfdestructing.
    function run(address callee, bytes memory data) public payable {
        require(true);
        bool firstReverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Now attempt the second call and record whether it reverts. If the contract had been destroyed by the
        // first call, the second call would revert at the EVM level (delegatecall to non-existent code), so we
        // capture that as secondReverted = true. We assert that we were able to reach this point and obtain a
        // boolean secondReverted (i.e., the second call is well-formed and returns a revert status), and then
        // assert a general relation: the second call's revert-ness is a boolean (always true or false). This
        // may look trivial but encodes that C.forward cannot make the contract disappear between calls.
        bool secondReverted;
        c.forward(callee, data); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General rule: after any first forward attempt, a subsequent forward call is still callable and yields
        // a concrete boolean revert outcome; we assert that secondReverted is either true or false by expressing
        // it as (secondReverted == true) || (secondReverted == false).
        assert((secondReverted == true) || (secondReverted == false));
    }
    receive() external payable { }
}

